import sys

tokens = sys.stdin.read().split()
tiles = [(int(t[0]), t[1]) for t in tokens]

def is_meld(ts):
    (a1, s1), (a2, s2), (a3, s3) = ts
    if ts[0] == ts[1] == ts[2]:
        return True
    if s1 == s2 == s3:
        nums = sorted([a1, a2, a3])
        if nums[1] == nums[0] + 1 and nums[2] == nums[1] + 1:
            return True
    return False

if is_meld(tiles):
    print(0)
else:
    ans = 2
    for i in range(3):
        for j in range(i + 1, 3):
            (a1, s1), (a2, s2) = tiles[i], tiles[j]
            if tiles[i] == tiles[j]:
                ans = 1
            elif s1 == s2 and abs(a1 - a2) in (1, 2):
                ans = 1
    print(ans)

