data = sys.stdin.read().strip().split()
n = int(data[0])
s = data[1]

totalG = s.count('G')
if totalG == 0:
    print(0)
    sys.exit(0)
if totalG == n:
    print(n)
    sys.exit(0)

leftG = [0]*n
rightG = [0]*n

for i in range(n):
    if s[i] == 'G':
        leftG[i] = (leftG[i-1] + 1) if i > 0 else 1
    else:
        leftG[i] = 0

for i in range(n-1, -1, -1):
    if s[i] == 'G':
        rightG[i] = (rightG[i+1] + 1) if i < n-1 else 1
    else:
        rightG[i] = 0

maxRun = max(leftG)
ans = maxRun
if totalG > maxRun:
    ans = max(ans, maxRun + 1)

for i in range(1, n-1):
    if s[i] == 'S':
        l = leftG[i-1]
        r = rightG[i+1]
        if l > 0 and r > 0:
            cand = l + r + 1
            if cand > totalG:
                cand = totalG
            if cand > ans:
                ans = cand

print(ans)

