import sys
from collections import deque

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    files = []
    for _ in range(n):
        s = next(it)
        t = int(next(it))
        files.append((s, t))
    e = sum(1 for _, t in files if t == 1)

    def good_num(s):
        if not s.isdigit():
            return None
        if s[0] == '0':
            return None
        x = int(s)
        if 1 <= x <= n:
            return x
        return None

    map_type = {}
    present_numbers = set()

    wrong_ex = deque()   # regular (0) occupying example slot (<=e): (name, number)
    wrong_reg = deque()  # example (1) occupying regular slot (>e): (name, number)
    others_ex = deque()  # example with non-good name
    others_reg = deque() # regular with non-good name

    for s, t in files:
        map_type[s] = t
        x = good_num(s)
        if x is not None:
            present_numbers.add(x)
            if x <= e:
                if t == 1:
                    pass  # correct
                else:
                    wrong_ex.append((s, x))
            else:
                if t == 0:
                    pass  # correct
                else:
                    wrong_reg.append((s, x))
        else:
            if t == 1:
                others_ex.append(s)
            else:
                others_reg.append(s)

    free_example = set(range(1, e + 1))
    free_regular = set(range(e + 1, n + 1))
    for x in present_numbers:
        if x <= e:
            if x in free_example:
                free_example.remove(x)
        else:
            if x in free_regular:
                free_regular.remove(x)

    moves = []

    def do_move(src, dst):
        moves.append((src, dst))
        t = map_type.pop(src)
        map_type[dst] = t

    def get_temp():
        k = n + 1
        while True:
            s = str(k)
            if s not in map_type:
                return s
            k += 1

    while wrong_ex or wrong_reg or others_ex or others_reg:
        # If no free slots, break cycle with temp
        if not free_example and not free_regular:
            tmp = get_temp()
            if wrong_reg:
                s, y = wrong_reg.popleft()
                do_move(s, tmp)
                others_ex.append(tmp)
                free_regular.add(y)
            else:
                s, y = wrong_ex.popleft()
                do_move(s, tmp)
                others_reg.append(tmp)
                free_example.add(y)
        # Fill example free slots
        while free_example and (wrong_reg or others_ex):
            x = free_example.pop()
            if wrong_reg:
                s, y = wrong_reg.popleft()
                do_move(s, str(x))
                free_regular.add(y)
            else:
                s = others_ex.popleft()
                do_move(s, str(x))
        # Fill regular free slots
        while free_regular and (wrong_ex or others_reg):
            x = free_regular.pop()
            if wrong_ex:
                s, y = wrong_ex.popleft()
                do_move(s, str(x))
                free_example.add(y)
            else:
                s = others_reg.popleft()
                do_move(s, str(x))

    print(len(moves))
    for a, b in moves:
        print("move", a, b)

if __name__ == "__main__":
    main()

import sys, random, math

def is_prime(n):
    if n < 2:
        return False
    small_primes = [2, 3, 5, 7, 11, 13, 17]
    for p in small_primes:
        if n % p == 0:
            return n == p
    d = n - 1
    s = 0
    while d % 2 == 0:
        s += 1
        d //= 2
    for a in small_primes:
        if a % n == 0:
            continue
        x = pow(a, d, n)
        if x == 1 or x == n - 1:
            continue
        for _ in range(s - 1):
            x = (x * x) % n
            if x == n - 1:
                break
        else:
            return False
    return True

def pollard_rho(n):
    if n % 2 == 0:
        return 2
    if n % 3 == 0:
        return 3
    while True:
        c = random.randrange(1, n - 1)
        f = lambda x: (pow(x, 2, n) + c) % n
        x = random.randrange(0, n)
        y = x
        d = 1
        while d == 1:
            x = f(x)
            y = f(f(y))
            d = math.gcd(abs(x - y), n)
        if d != n:
            return d

def factor(n, res):
    if n == 1:
        return
    if is_prime(n):
        res[n] = res.get(n, 0) + 1
        return
    d = pollard_rho(n)
    factor(d, res)
    factor(n // d, res)

def factor_dict(n):
    res = {}
    factor(n, res)
    return res

def lcm(a, b):
    return a // math.gcd(a, b) * b

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    m = int(data[0])
    x = int(data[1])
    fm = factor_dict(m)
    primes = list(fm.keys())
    exps = [fm[p] for p in primes]
    ord_pows = []
    phi_contribs = []
    for p, e in zip(primes, exps):
        ord_list = [1] * (e + 1)
        phi_list = [1] * (e + 1)
        for a in range(1, e + 1):
            phi_list[a] = (p - 1) * pow(p, a - 1)
        if p == 2:
            r = 1
            ord_list[1] = r
            for a in range(2, e + 1):
                mod = 1 << a
                if pow(x, r, mod) == 1:
                    ord_list[a] = r
                else:
                    r *= 2
                    ord_list[a] = r
        else:
            pm1 = p - 1
            fpm1 = factor_dict(pm1)
            r = pm1
            for q in fpm1:
                while r % q == 0 and pow(x, r // q, p) == 1:
                    r //= q
            ord_list[1] = r
            for a in range(2, e + 1):
                mod = pow(p, a)
                if pow(x, r, mod) == 1:
                    ord_list[a] = r
                else:
                    r *= p
                    ord_list[a] = r
        ord_pows.append(ord_list)
        phi_contribs.append(phi_list)
    ans = 0
    def dfs(i, cur_phi, cur_ord):
        nonlocal ans
        if i == len(primes):
            ans += cur_phi // cur_ord
            return
        e = exps[i]
        for a in range(e + 1):
            new_phi = cur_phi * phi_contribs[i][a]
            new_ord = lcm(cur_ord, ord_pows[i][a])
            dfs(i + 1, new_phi, new_ord)
    dfs(0, 1, 1)
    print(ans)

if __name__ == "__main__":
    main()

