import sys

def is_prime(n):
    if n < 2:
        return False
    small_primes = [2, 3, 5, 7, 11]
    for p in small_primes:
        if n % p == 0:
            return n == p
    d = n - 1
    s = 0
    while d % 2 == 0:
        d //= 2
        s += 1
    for a in small_primes:
        if a % n == 0:
            continue
        x = pow(a, d, n)
        if x == 1 or x == n - 1:
            continue
        for _ in range(s - 1):
            x = (x * x) % n
            if x == n - 1:
                break
        else:
            return False
    return True

def sieve(limit):
    if limit < 2:
        return []
    bs = bytearray(b'\x01') * (limit + 1)
    bs[0:2] = b'\x00\x00'
    i = 2
    while i * i <= limit:
        if bs[i]:
            step = i
            start = i * i
            bs[start:limit+1:step] = b'\x00' * (((limit - start) // step) + 1)
        i += 1
    return [i for i in range(limit + 1) if bs[i]]

def find_two_primes_sum(m):
    L = 2_000_000
    lim = min(L, m)
    primes = sieve(lim)
    for p in primes:
        q = m - p
        if q >= 2 and is_prime(q):
            return p, q
    # Fallback search beyond sieve limit if needed
    a = lim + 1 + ((lim + 1) % 2 == 0)
    while a <= m - 3:
        if is_prime(a):
            b = m - a
            if b >= 2 and is_prime(b):
                return a, b
        a += 2
    return None

