import sys

def main():
    data = sys.stdin.read().splitlines()
    if not data:
        return
    n, m = map(int, data[0].split())
    grid = [list(line.rstrip('\n')) for line in data[1:1+n]]

    rmin, rmax = n, -1
    cmin, cmax = m, -1
    whites = []
    for i in range(n):
        row = grid[i]
        for j in range(m):
            if row[j] == 'w':
                whites.append((i, j))
                if i < rmin: rmin = i
                if i > rmax: rmax = i
                if j < cmin: cmin = j
                if j > cmax: cmax = j

    if not whites:
        # As per problem, guaranteed at least one white, but handle just in case
        print(-1)
        return

    H = rmax - rmin + 1
    W = cmax - cmin + 1
    d = max(H, W)

    if d > n or d > m:
        print(-1)
        return

    hasInside = False
    intRowsCmin = False
    intRowsCmax = False
    intColsRmin = False
    intColsRmax = False

    for i, j in whites:
        if rmin < i < rmax and cmin < j < cmax:
            hasInside = True
            break
        if H > W and rmin < i < rmax:
            if j == cmin:
                intRowsCmin = True
            if j == cmax:
                intRowsCmax = True
        if W > H and cmin < j < cmax:
            if i == rmin:
                intColsRmin = True
            if i == rmax:
                intColsRmax = True

    if hasInside:
        print(-1)
        return

    r = 0
    c = 0
    if H == W:
        r = rmin
        c = cmin
    elif H > W:
        # r fixed
        r = rmin
        # If both extremes appear in interior rows and are different, impossible
        if cmin != cmax and intRowsCmin and intRowsCmax:
            print(-1)
            return
        if intRowsCmin:
            c = cmin
            if c > m - d:
                print(-1)
                return
        elif intRowsCmax:
            c = cmax - d + 1
            if c < 0:
                print(-1)
                return
        else:
            lower = max(0, cmax - d + 1)
            upper = min(cmin, m - d)
            if lower > upper:
                print(-1)
                return
            # any c in [lower, upper]
            c = min(cmin, m - d)
            if c < lower:
                c = lower
    else:  # W > H
        c = cmin
        if rmin != rmax and intColsRmin and intColsRmax:
            print(-1)
            return
        if intColsRmin:
            r = rmin
            if r > n - d:
                print(-1)
                return
        elif intColsRmax:
            r = rmax - d + 1
            if r < 0:
                print(-1)
                return
        else:
            lower = max(0, rmax - d + 1)
            upper = min(rmin, n - d)
            if lower > upper:
                print(-1)
                return
            r = min(rmin, n - d)
            if r < lower:
                r = lower

    # Final validation
    for i, j in whites:
        if not (r <= i <= r + d - 1 and c <= j <= c + d - 1):
            print(-1)
            return
        if not (i == r or i == r + d - 1 or j == c or j == c + d - 1):
