def build_left(a, l, r):
    if l == r:
        return str(a[l])
    k = r - l
    parts = []
    parts.append("(" * k)
    parts.append(str(a[l]))
    for i in range(l + 1, r + 1):
        parts.append("->")
        parts.append(str(a[i]))
        parts.append(")")
    return "".join(parts)

def build_right(a, l, r):
    if l == r:
        return str(a[l])
    parts = []
    parts.append(str(a[l]))
    for i in range(l + 1, r + 1):
        parts.append("->(")
        parts.append(str(a[i]))
    parts.append(")" * (r - l))
    return "".join(parts)

