import sys
from collections import deque

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    files = []
    for _ in range(n):
        s = next(it)
        t = int(next(it))
        files.append((s, t))
    e = sum(1 for _, t in files if t == 1)

    def good_num(s):
        if not s.isdigit():
            return None
        if s[0] == '0':
            return None
        x = int(s)
        if 1 <= x <= n:
            return x
        return None

    map_type = {}
    present_numbers = set()

    wrong_ex = deque()   # regular (0) occupying example slot (<=e): (name, number)
    wrong_reg = deque()  # example (1) occupying regular slot (>e): (name, number)
    others_ex = deque()  # example with non-good name
    others_reg = deque() # regular with non-good name

    for s, t in files:
        map_type[s] = t
        x = good_num(s)
        if x is not None:
            present_numbers.add(x)
            if x <= e:
                if t == 1:
                    pass  # correct
                else:
                    wrong_ex.append((s, x))
            else:
                if t == 0:
                    pass  # correct
                else:
                    wrong_reg.append((s, x))
        else:
            if t == 1:
                others_ex.append(s)
            else:
                others_reg.append(s)

    free_example = set(range(1, e + 1))
    free_regular = set(range(e + 1, n + 1))
    for x in present_numbers:
        if x <= e:
            if x in free_example:
                free_example.remove(x)
        else:
            if x in free_regular:
                free_regular.remove(x)

    moves = []

    def do_move(src, dst):
        moves.append((src, dst))
        t = map_type.pop(src)
        map_type[dst] = t

    def get_temp():
        k = n + 1
        while True:
            s = str(k)
            if s not in map_type:
                return s
            k += 1

    while wrong_ex or wrong_reg or others_ex or others_reg:
        # If no free slots, break cycle with temp
        if not free_example and not free_regular:
            tmp = get_temp()
            if wrong_reg:
                s, y = wrong_reg.popleft()
                do_move(s, tmp)
                others_ex.append(tmp)
                free_regular.add(y)
            else:
                s, y = wrong_ex.popleft()
                do_move(s, tmp)
                others_reg.append(tmp)
                free_example.add(y)
        # Fill example free slots
        while free_example and (wrong_reg or others_ex):
            x = free_example.pop()
            if wrong_reg:
                s, y = wrong_reg.popleft()
                do_move(s, str(x))
                free_regular.add(y)
            else:
                s = others_ex.popleft()
                do_move(s, str(x))
        # Fill regular free slots
        while free_regular and (wrong_ex or others_reg):
            x = free_regular.pop()
            if wrong_ex:
                s, y = wrong_ex.popleft()
                do_move(s, str(x))
                free_example.add(y)
            else:
                s = others_reg.popleft()
                do_move(s, str(x))

    print(len(moves))
    for a, b in moves:
        print("move", a, b)

