import sys, random, math

def is_prime(n):
    if n < 2:
        return False
    small_primes = [2, 3, 5, 7, 11, 13, 17]
    for p in small_primes:
        if n % p == 0:
            return n == p
    d = n - 1
    s = 0
    while d % 2 == 0:
        s += 1
        d //= 2
    for a in small_primes:
        if a % n == 0:
            continue
        x = pow(a, d, n)
        if x == 1 or x == n - 1:
            continue
        for _ in range(s - 1):
            x = (x * x) % n
            if x == n - 1:
                break
        else:
            return False
    return True

def pollard_rho(n):
    if n % 2 == 0:
        return 2
    if n % 3 == 0:
        return 3
    while True:
        c = random.randrange(1, n - 1)
        f = lambda x: (pow(x, 2, n) + c) % n
        x = random.randrange(0, n)
        y = x
        d = 1
        while d == 1:
            x = f(x)
            y = f(f(y))
            d = math.gcd(abs(x - y), n)
        if d != n:
            return d

def factor(n, res):
    if n == 1:
        return
    if is_prime(n):
        res[n] = res.get(n, 0) + 1
        return
    d = pollard_rho(n)
    factor(d, res)
    factor(n // d, res)

def factor_dict(n):
    res = {}
    factor(n, res)
    return res

def lcm(a, b):
    return a // math.gcd(a, b) * b

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    m = int(data[0])
    x = int(data[1])
    fm = factor_dict(m)
    primes = list(fm.keys())
    exps = [fm[p] for p in primes]
    ord_pows = []
    phi_contribs = []
    for p, e in zip(primes, exps):
        ord_list = [1] * (e + 1)
        phi_list = [1] * (e + 1)
        for a in range(1, e + 1):
            phi_list[a] = (p - 1) * pow(p, a - 1)
        if p == 2:
            r = 1
            ord_list[1] = r
            for a in range(2, e + 1):
                mod = 1 << a
                if pow(x, r, mod) == 1:
                    ord_list[a] = r
                else:
                    r *= 2
                    ord_list[a] = r
        else:
            pm1 = p - 1
            fpm1 = factor_dict(pm1)
            r = pm1
            for q in fpm1:
                while r % q == 0 and pow(x, r // q, p) == 1:
                    r //= q
            ord_list[1] = r
            for a in range(2, e + 1):
                mod = pow(p, a)
                if pow(x, r, mod) == 1:
                    ord_list[a] = r
                else:
                    r *= p
                    ord_list[a] = r
        ord_pows.append(ord_list)
        phi_contribs.append(phi_list)
    ans = 0
    def dfs(i, cur_phi, cur_ord):
        nonlocal ans
        if i == len(primes):
            ans += cur_phi // cur_ord
            return
        e = exps[i]
        for a in range(e + 1):
            new_phi = cur_phi * phi_contribs[i][a]
            new_ord = lcm(cur_ord, ord_pows[i][a])
            dfs(i + 1, new_phi, new_ord)
    dfs(0, 1, 1)
    print(ans)

