import sys

def build_pi(s):
    m = len(s)
    pi = [0] * m
    for i in range(1, m):
        j = pi[i - 1]
        while j > 0 and s[i] != s[j]:
            j = pi[j - 1]
        if s[i] == s[j]:
            j += 1
        pi[i] = j
    return pi

def next_state(s, pi, q, c):
    while q > 0 and s[q] != c:
        q = pi[q - 1]
    if s[q] == c:
        q += 1
    return q

def mat_mul(A, B):
    n = len(A)
    C = [[0] * n for _ in range(n)]
    for i in range(n):
        Ai = A[i]
        Ci = C[i]
        for k in range(n):
            a = Ai[k]
            if a == 0:
                continue
            Bk = B[k]
            for j in range(n):
                if Bk[j]:
                    Ci[j] += a * Bk[j]
    return C

def mat_pow(M, e):
    n = len(M)
    # Identity
    R = [[0] * n for _ in range(n)]
    for i in range(n):
        R[i][i] = 1
    base = M
    while e > 0:
        if e & 1:
            R = mat_mul(R, base)
        base = mat_mul(base, base)
        e >>= 1
    return R

