import sys

def count_le(n, m, x):
    limit = n if n < x else x
    t = x // m
    if t > limit:
        t = limit
    cnt = m * t
    i = t + 1
    while i <= limit:
        q = x // i
        if q == 0:
            break
        r = x // q
        if r > limit:
            r = limit
        cnt += q * (r - i + 1)
        i = r + 1
    return cnt

def kth_number(n, m, k):
    if n > m:
        n, m = m, n
    low, high = 1, n * m
    while low < high:
        mid = (low + high) // 2
        if count_le(n, m, mid) < k:
            low = mid + 1
        else:
            high = mid
    return low

