        break

if t == -1:
    print("NO")
    sys.exit()

E1 = build_left(a, 1, t)
E2 = build_right(a, t + 1, n - 1)
E = "(" + E1 + "->" + E2 + ")"
expr = "(" + E + "->" + str(a[n]) + ")"
out.append("YES")
out.append(expr)
print("\n".join(out))

import sys

data = sys.stdin.read().splitlines()
if not data:
    print("Impossible")
    sys.exit()

s = data[0].strip()
k = int(data[1].strip()) if len(data) > 1 else 0

pairs = []
i = 0
n = len(s)
while i < n:
    ch = s[i]
    if 'a' <= ch <= 'z':
        mod = None
        if i + 1 < n and s[i + 1] in ('?', '*'):
            mod = s[i + 1]
            i += 2
        else:
            i += 1
        pairs.append((ch, mod))
    else:
        i += 1

L = len(pairs)
count_star = sum(1 for _, m in pairs if m == '*')
count_mand = sum(1 for _, m in pairs if m is None)
min_len = count_mand

if k < min_len:
    print("Impossible")
    sys.exit()
if count_star == 0 and k > L:
    print("Impossible")
    sys.exit()

res = []

if k <= L:
    surplus = L - k
    for ch, m in pairs:
        if surplus > 0 and (m == '?' or m == '*'):
            surplus -= 1
            continue
        res.append(ch)
else:
    need = k - L
    chosen = False
    for ch, m in pairs:
        if not chosen and m == '*':
            res.append(ch * (1 + need))
            chosen = True
        else:
            res.append(ch)

print(''.join(res))

import sys

vals = list(map(int, sys.stdin.read().strip().split()))
if len(vals) < 6:
    print("No")
else:
    a, b, c, x, y, z = vals[:6]
    surplus_pairs = 0
    deficit = 0
    for have, need in ((a, x), (b, y), (c, z)):
        if have >= need:
            surplus_pairs += (have - need) // 2
        else:
            deficit += need - have
    print("Yes" if surplus_pairs >= deficit else "No")

